const char *filepath = "/path/to/file";

// Standard POSIX modes for access()
// R_OK (Read), W_OK (Write), X_OK (Execute), F_OK (Existence)

// Check existence only
if (access(filepath, F_OK) == 0) {
    // File exists
}

// Check for effective Read/Write permissions
int required_mode = R_OK | W_OK;

if (access(filepath, required_mode) == 0) {
    // R/W access granted
} else if (errno == EACCES) {
    // Permission denied by file bits/UID/GID
}

// Check against real IDs (e.g., faccessat(AT_FDCWD, ..., mode, AT_EACCESS))
// Often preferred over access() for security checks.
